{
  "name": "文件接口设备",
  "name_en": "File-based Device Interface",
  "manufacturer": "",
  "description": "这是一个通过文件或流式接口进行读写的通用设备连接对象。根据现有证据，无法可靠确定其对应的具体物理仪器型号；它更像是实验室仪器通信中使用的底层输入输出端点，用于向设备写入命令、读取返回数据并关闭连接。",
  "description_en": "This is a generic device connection exposed through a file or stream-style read/write interface. Based on the available evidence, the specific physical instrument cannot be identified reliably; it appears to be a low-level I/O endpoint used in laboratory instrument communication for writing commands, reading returned data, and closing the connection.",
  "actions": [
    {
      "action_name": "auto-write",
      "description": "向设备连接写入数据",
      "description_en": "Write data to the device connection"
    },
    {
      "action_name": "auto-read",
      "description": "从设备连接读取数据",
      "description_en": "Read data from the device connection"
    },
    {
      "action_name": "auto-close",
      "description": "关闭设备连接",
      "description_en": "Close the device connection"
    }
  ],
  "tag_hints": [
    "file I/O",
    "instrument communication",
    "read/write interface",
    "stream connection",
    "generic lab device link"
  ]
}

